import { Component, inject } from "@angular/core";
import { FormBuilder, Validators } from "@angular/forms";
import { Subject, tap, filter, exhaustMap } from "rxjs";
import { TestingService } from "../../services/testing.service";
import { environment } from "../../../environments/environment";

@Component({
  selector: "app-form",
  imports: [],
  template: ``,
  styles: ``,
})
export class FormComponent {
  private testingService = inject(TestingService);
  private fb = inject(FormBuilder);

  constructor() {
    this.subscribeToSubmited();
  }

  albums: any;
  loading = false;
  submited$: Subject<void> = new Subject<void>();

  form = this.fb.group({
    name: ["", Validators.required],
    email: ["", [Validators.required, Validators.email]],
    password: ["", [Validators.required, Validators.minLength(6)]],
  });

  subscribeToSubmited() {
    this.submited$
      .pipe(
        tap(() => (this.loading = true)),
        filter(() => this.form.valid),
        exhaustMap(() => {
          const { name, email, password } = this.form.value;
          const data = { name, email, password };
          return this.testingService.validateUser(data);
        }),
      )
      .subscribe({
        next: (data) => {
          this.albums = data;
          this.loading = false;
        },
        error: (error) => {
          const errorCode: keyof typeof environment.errorMessages =
            error.listErrorDto.code;
          const errorMessages =
            environment.errorMessages[errorCode] || "Error desconocido";
          this.albums = errorMessages;
          this.loading = false;
        },
      });
  }
}
```



Con la guía proporcionada sobre cómo realizar pruebas de solicitudes HTTP en Angular, puedes aplicar varios conceptos y técnicas para mejorar y asegurar la calidad de las pruebas en tu componente `FormComponent`. Aquí te detallo cómo puedes aplicar estos conceptos en tu archivo de pruebas `form.component.spec.ts`.

### Configuración de TestBed

Ya tienes configurado `TestBed` para incluir `provideHttpClient()` y `provideHttpClientTesting()`, lo cual es correcto y necesario para usar `HttpTestingController` en tus pruebas.

```typescript
beforeEach(async () => {
  await TestBed.configureTestingModule({
    imports: [FormComponent],
    providers: [provideHttpClient(), provideHttpClientTesting()],
  }).compileComponents();

  fixture = TestBed.createComponent(FormComponent);
  component = fixture.componentInstance;
  httpTestingController = TestBed.inject(HttpTestingController);
  testingService = TestBed.inject(TestingService);

  component.form = component["fb"].group({
    name: ["name", Validators.required],
    email: ["email@gmail.com", [Validators.required, Validators.email]],
    password: ["password", [Validators.required, Validators.minLength(6)]],
  });

  fixture.detectChanges();
});

afterEach(() => {
  httpTestingController.verify();
});
```

### Prueba de éxito en el registro de usuario

En la prueba `should regist user success`, puedes usar `HttpTestingController` para interceptar la solicitud HTTP y proporcionar una respuesta simulada.

```typescript
it("should regist user success", () => {
  const userMock = { name: "name", email: "email", password: "password" };
  spyOn(testingService, "validateUser").and.callThrough();

  component.form.setValue({
    name: "name",
    email: "email@email.com",
    password: "password",
  });

  component.subscribeToSubmited();
  component.submited$.next();

  const req = httpTestingController.expectOne('/api/validateUser');
  expect(req.request.method).toBe('POST');
  req.flush(userMock);

  expect(component.albums).toEqual(userMock);
  expect(component["loading"]).toEqual(false);
});
```

### Prueba de manejo de errores

En la prueba `should handle error`, puedes simular diferentes respuestas de error del backend y verificar que el componente maneja estos errores correctamente.

```typescript
it("should handle error", () => {
  const errorCodes = [
    "SFB0000",
    "SFB0001",
    "SFB0002",
    "SFB0003",
    "SFB0004",
    "SFB0005",
    "SFB0006",
    "SFB0007",
  ];

  component.form.setValue({
    name: "name",
    email: "email@gmail.com",
    password: "password",
  });

  const spy = spyOn(testingService, "validateUser").and.callThrough();

  errorCodes.forEach((code) => {
    const errorMock = { listErrorDto: { code } };
    spy.and.returnValue(throwError(() => errorMock));

    component.subscribeToSubmited();
    component.submited$.next();

    const req = httpTestingController.expectOne('/api/validateUser');
    req.flush(errorMock, { status: 400, statusText: 'Bad Request' });

    expect(component["loading"]).toEqual(false);

    const codeType = code as keyof typeof environment.errorMessages;
    const expectedMessage =
      environment.errorMessages[codeType] || "Error desconocido";
    expect(component.albums).toEqual(expectedMessage);
  });
});
```

### Resumen

1. **Configuración de TestBed**: Asegúrate de configurar `TestBed` con `provideHttpClient()` y `provideHttpClientTesting()` para usar `HttpTestingController`.
2. **Interceptar solicitudes HTTP**: Usa `HttpTestingController` para interceptar solicitudes HTTP y proporcionar respuestas simuladas en tus pruebas.
3. **Verificar solicitudes**: Verifica que las solicitudes HTTP se realicen con los métodos y URLs correctos.
4. **Simular errores del backend**: Simula respuestas de error del backend y verifica que tu componente maneje estos errores correctamente.

Aplicando estos conceptos, puedes mejorar la robustez y la cobertura de tus pruebas para el componente `FormComponent`.
